using DAL;
using Microsoft.Extensions.DependencyInjection;
using Utils.Interface;
namespace Tests;
public class TcsReportTests(ApiFactory f):ApiTest(f)
{
    [Fact]public async Task Tcs_report_IST_month_sales_cancellations_returns_and_odd_negative_tax_split()
    {
        var admin=await Admin();var user=await LoginPhone("9890000095");Assert.Equal(403,(await user.Get("/api/admin/reports/tcs?month=2026-11")).Status);var r=await admin.Get("/api/admin/reports/tcs?month=2026-11");Assert.True(r.Status==200,r.ToString());Assert.Empty(r.Json["items"]!.AsArray());Assert.Equal(422,(await admin.Get("/api/admin/reports/tcs?month=2026-13")).Status);Assert.Equal(422,(await admin.Get("/api/admin/reports/tcs")).Status);
        var sid=(await user.Post("/api/seller/register",new{display_name="Synthetic TCS Store"})).Json["id"]!.GetValue<string>();await ApiFactory.DbExecAsync("UPDATE sellers SET legal_name='Synthetic TCS Legal' WHERE id=@sid",new{sid});var cat=Guid.NewGuid();await ApiFactory.DbExecAsync("INSERT INTO categories(id,name,slug,image_url,commission_bps,default_gst_bps,position,is_active,required_details)VALUES(@cat,'Synthetic TCS','synthetic-tcs','',500,500,0,1,'[]')",new{cat});var product=(await user.Post("/api/seller/products",new{category_id=cat,title="Synthetic TCS Product",hsn_code="6205",gst_bps=500,variants=new[]{new{sku="TCS-SKU",price_paise=10000,mrp_paise=20000,stock=10}}})).Json;var pid=product["id"]!.GetValue<string>();var vid=product["variants"]![0]!["id"]!.GetValue<string>();
        using var scope=Factory.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<IMySqlDapperHelper>();var orders=scope.ServiceProvider.GetRequiredService<OrdersDAL>();var start=new DateTime(2026,10,31,18,30,0);var subs=new List<Guid>();await using(var tx=await db.BeginAsync()){for(var i=0;i<4;i++){var oid=Guid.NewGuid();var sub=Guid.NewGuid();subs.Add(sub);await orders.InsertOrderAsync(new(){Id=oid,Number="SYNTH-TCS-"+i,UserId=Guid.Parse(user.Id),Status="placed",PaymentMethod="cod",PaymentStatus="cod",ShipTo="{}",ItemsTotal=10000,GrandTotal=10000,Currency="INR",FxRate=1,Fees="[]",IdempotencyKey=Guid.NewGuid().ToString(),PlacedAt=i==2?start.AddSeconds(-1):i==3?start.AddMonths(1):start,CreatedAt=start,UpdatedAt=start},tx);await orders.InsertSubOrderAsync(new(){Id=sub,OrderId=oid,SellerId=Guid.Parse(sid),Number="SYNTH-TCS-PKG-"+i,Status=i==1?"cancelled":"delivered",SettlementStatus="pending",TaxableTotal=10000,TcsPaise=101,IsInterstate=false,CreatedAt=start,UpdatedAt=start},tx);}var item=Guid.NewGuid();await orders.InsertOrderItemAsync(new(){Id=item,SubOrderId=subs[2],ProductId=Guid.Parse(pid),VariantId=Guid.Parse(vid),Title="Synthetic",Qty=3,UnitPrice=10000,UnitMrp=20000,LineTotal=30000,TaxableValue=10001,Igst=19999},tx);await tx.ExecuteAsync("INSERT INTO return_requests(id,number,sub_order_id,seller_id,user_id,status,reason,comment,refund_amount,refund_upi,seller_note,pickup_courier,pickup_tracking,credit_note_number,received_at)VALUES(@rid,'SYNTH-TCS-RETURN',@sub,@sid,@uid,'received','other','',10000,'','','','','',@at)",new{rid=item,sub=subs[2],sid,uid=user.Id,at=start});await tx.ExecuteAsync("INSERT INTO return_items(id,return_id,order_item_id,qty,amount)VALUES(UUID(),@item,@item,1,10000)",new{item});await tx.ExecuteAsync("INSERT INTO seller_ledger(id,seller_id,sub_order_id,kind,amount,available_at,description,created_at)VALUES(UUID(),@sid,@sub,'tcs_reversal',51,@at,'Synthetic reversal',@at)",new{sid,sub=subs[2],at=start});await tx.CommitAsync();}
        r=await admin.Get("/api/admin/reports/tcs?month=2026-11");Assert.True(r.Status==200,r.ToString());Assert.Single(r.Json["items"]!.AsArray());var row=r.Json["items"]![0]!;Assert.Equal(6667,row["net_taxable_value"]!.GetValue<long>());Assert.Equal(3333,row["returned_value"]!.GetValue<long>());Assert.Equal(1,row["sub_orders"]!.GetValue<long>());Assert.Equal(25,row["cgst_tcs"]!.GetValue<long>());Assert.Equal(25,row["sgst_tcs"]!.GetValue<long>());Assert.Equal(0,row["igst_tcs"]!.GetValue<long>());Assert.Equal(6667,r.Json["totals"]!["net_taxable_value"]!.GetValue<long>());
        await ApiFactory.DbExecAsync("UPDATE sub_orders SET is_interstate=1 WHERE id=@id",new{id=subs[2]});r=await admin.Get("/api/admin/reports/tcs?month=2026-11");row=r.Json["items"]![0]!;Assert.Equal(-51,row["igst_tcs"]!.GetValue<long>());Assert.Equal(50,row["cgst_tcs"]!.GetValue<long>());Assert.Equal(51,row["sgst_tcs"]!.GetValue<long>());
    }
}
